import { Readable } from 'node:stream';

export interface ObjectStat { size: number; contentType: string | null }
export interface ObjectRead { stream: Readable; size: number; contentType: string | null; /** Set when a range was requested. */ range?: { start: number; end: number; total: number } }
export interface UploadAuthorization { url: string; method: 'PUT'; headers: Record<string, string>; expiresAt: Date }

/** Object keys are generated by the server, but every storage call re-validates them: no traversal, no odd characters. */
const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9/_.=-]{0,500}$/;
export function assertSafeKey(key: string): string {
  if (!SAFE_KEY.test(key) || key.includes('..') || key.includes('//')) throw new Error(`Unsafe storage key: ${key.slice(0, 80)}`);
  return key;
}

/**
 * Object storage boundary. Video bytes NEVER touch MySQL; the database holds only keys and metadata.
 * Two implementations: S3-compatible (Amazon S3, Cloudflare R2) for real use, and a local folder for development.
 */
export abstract class StorageService {
  abstract readonly driver: 's3' | 'local';
  abstract put(key: string, body: Buffer | Readable, contentType: string): Promise<void>;
  abstract uploadFile(key: string, filePath: string, contentType: string): Promise<void>;
  abstract get(key: string, range?: { start: number; end?: number }): Promise<ObjectRead | null>;
  abstract stat(key: string): Promise<ObjectStat | null>;
  abstract downloadTo(key: string, filePath: string): Promise<void>;
  abstract delete(key: string): Promise<void>;
  /** Deletes every object whose key starts with `prefix` (which must end with "/"). */
  abstract deletePrefix(prefix: string): Promise<number>;
  /** A short-lived, single-object, write-only authorisation for the browser/uploader. The size is verified again on completion. */
  abstract createUploadAuthorization(key: string, contentType: string, sizeBytes: number, ttlSeconds: number): Promise<UploadAuthorization>;
  /** A short-lived read URL, or null if this driver must be streamed through the API. */
  abstract presignGet(key: string, ttlSeconds: number): Promise<string | null>;
}
